// Object storage abstraction. Production uses S3 (or any S3-compatible service); local development
// and tests use the filesystem driver. Keys are generated by us, never taken verbatim from users.

import { mkdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import {
  DeleteObjectCommand,
  GetObjectCommand,
  HeadBucketCommand,
  HeadObjectCommand,
  PutObjectCommand,
  S3Client,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { env } from "./env";
import { sha256Hex } from "./crypto";

export interface StoredObject {
  key: string;
  sizeBytes: number;
  checksumSha256: string;
  contentType: string;
}

export interface StorageDriver {
  readonly name: "local" | "s3";
  put(key: string, body: Buffer, contentType: string): Promise<StoredObject>;
  get(key: string): Promise<Buffer>;
  exists(key: string): Promise<boolean>;
  delete(key: string): Promise<void>;
  /** Short-lived URL for previews; local driver returns an authenticated app route. */
  previewUrl(key: string, expiresInSeconds?: number): Promise<string>;
  healthCheck(): Promise<void>;
}

const KEY_PATTERN = /^[a-z0-9][a-z0-9/_.-]{0,511}$/;

export function assertValidKey(key: string): void {
  if (!KEY_PATTERN.test(key) || key.includes("..") || key.includes("//")) throw new Error(`Invalid storage key: ${key}`);
}

/** e.g. creators/<creatorId>/images/2026/10/<uuid>.png */
export function buildStorageKey(parts: { creatorId?: string | null; kind: string; id: string; extension: string }, now = new Date()) {
  const owner = parts.creatorId ? `creators/${parts.creatorId}` : "shared";
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, "0");
  const key = `${owner}/${parts.kind}/${y}/${m}/${parts.id}.${parts.extension.replace(/^\./, "")}`.toLowerCase();
  assertValidKey(key);
  return key;
}

export class LocalStorageDriver implements StorageDriver {
  readonly name = "local" as const;
  constructor(private readonly root: string) {}

  private resolve(key: string): string {
    assertValidKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Storage key escapes root");
    return full;
  }

  async put(key: string, body: Buffer, contentType: string): Promise<StoredObject> {
    const file = this.resolve(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, body, { flag: "wx" }); // never overwrite: keys are content-unique
    return { key, sizeBytes: body.length, checksumSha256: sha256Hex(body), contentType };
  }

  async get(key: string): Promise<Buffer> {
    return readFile(this.resolve(key));
  }

  async exists(key: string): Promise<boolean> {
    try {
      await stat(this.resolve(key));
      return true;
    } catch {
      return false;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.resolve(key), { force: true });
  }

  async previewUrl(key: string): Promise<string> {
    assertValidKey(key);
    return `/api/media/${key}`;
  }

  async healthCheck(): Promise<void> {
    await mkdir(this.root, { recursive: true });
    const probe = path.join(this.root, ".healthcheck");
    await writeFile(probe, String(Date.now()));
    await rm(probe, { force: true });
  }
}

export class S3StorageDriver implements StorageDriver {
  readonly name = "s3" as const;
  private readonly client: S3Client;

  constructor(
    private readonly bucket: string,
    region: string,
    endpoint?: string,
    forcePathStyle = false,
  ) {
    this.client = new S3Client({ region, endpoint, forcePathStyle });
  }

  async put(key: string, body: Buffer, contentType: string): Promise<StoredObject> {
    assertValidKey(key);
    const checksumSha256 = sha256Hex(body);
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: body,
        ContentType: contentType,
        ChecksumSHA256: Buffer.from(checksumSha256, "hex").toString("base64"),
        ServerSideEncryption: "AES256",
        IfNoneMatch: "*",
      }),
    );
    return { key, sizeBytes: body.length, checksumSha256, contentType };
  }

  async get(key: string): Promise<Buffer> {
    assertValidKey(key);
    const out = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    return Buffer.from(await out.Body!.transformToByteArray());
  }

  async exists(key: string): Promise<boolean> {
    assertValidKey(key);
    try {
      await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: key }));
      return true;
    } catch (err) {
      if ((err as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode === 404) return false;
      throw err;
    }
  }

  async delete(key: string): Promise<void> {
    assertValidKey(key);
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }

  async previewUrl(key: string, expiresInSeconds = 300): Promise<string> {
    assertValidKey(key);
    return getSignedUrl(this.client, new GetObjectCommand({ Bucket: this.bucket, Key: key }), { expiresIn: expiresInSeconds });
  }

  async healthCheck(): Promise<void> {
    await this.client.send(new HeadBucketCommand({ Bucket: this.bucket }));
  }
}

let driver: StorageDriver | undefined;

export function storage(): StorageDriver {
  if (driver) return driver;
  const e = env();
  driver =
    e.STORAGE_DRIVER === "s3"
      ? new S3StorageDriver(e.S3_BUCKET!, e.S3_REGION!, e.S3_ENDPOINT, e.S3_FORCE_PATH_STYLE)
      : new LocalStorageDriver(path.resolve(e.STORAGE_LOCAL_DIR));
  return driver;
}
